import{describe,it,expect}from"vitest";import{dashboardMetrics,dashboardSections,featuredDestinations,dashboardItems,getSectionById,getFeaturedDestinationById,filterDashboardItems}from"../../frontend/up-dashboard/up-dashboard.js";const MANDATORY_SECTION_IDS=["heritage","religious","cuisine","festivals","circuits","wildlife","handicrafts","history","games","districts"];describe("UP Tourism Dashboard Metrics & Sections Integrity",()=>{it("contains expected state tourism metrics",()=>{expect(dashboardMetrics.districtsCount).toBe(75),expect(dashboardMetrics.unescoSites).toBe(3),expect(dashboardMetrics.culturalCircuits).toBeGreaterThan(0)}),it("contains all 10 mandatory dashboard sections",()=>{expect(dashboardSections.length).toBe(10);const e=dashboardSections.map(e=>e.id.toLowerCase());MANDATORY_SECTION_IDS.forEach(t=>{expect(e).toContain(t)})}),it("every section object contains required fields with valid types",()=>{dashboardSections.forEach((e,t)=>{expect(e,`Section at index ${t} missing required properties`).toHaveProperty("id"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("icon"),expect(e).toHaveProperty("category"),expect(e).toHaveProperty("description"),expect(e).toHaveProperty("linkUrl"),expect(typeof e.id).toBe("string"),expect(typeof e.title).toBe("string"),expect(typeof e.description).toBe("string"),expect(typeof e.linkUrl).toBe("string")})})}),describe("Featured Destinations Carousel Dataset",()=>{it("contains at least 6 featured destinations for the carousel",()=>{expect(featuredDestinations.length).toBeGreaterThanOrEqual(6)}),it("every featured destination contains required properties",()=>{featuredDestinations.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("city"),expect(e).toHaveProperty("imageIcon"),expect(e).toHaveProperty("category"),expect(e).toHaveProperty("description"),expect(e).toHaveProperty("highlights"),expect(Array.isArray(e.highlights)).toBe(!0)})}),it("retrieves featured destination by ID",()=>{const e=getFeaturedDestinationById("feat-1");expect(e).toBeDefined(),expect(e.title).toBe("Taj Mahal")})}),describe("Dashboard Section & Unified Items Query Helpers",()=>{it("retrieves section by ID or category",()=>{const e=getSectionById("heritage");expect(e).toBeDefined(),expect(e.title).toBe("Heritage Sites");const t=getSectionById("Cuisine");expect(t).toBeDefined(),expect(t.id).toBe("cuisine")}),it("filters dashboard items by search query (e.g. Kebabs or Taj)",()=>{const e=filterDashboardItems("Taj Mahal");expect(e.length).toBeGreaterThan(0),expect(e[0].title).toBe("Taj Mahal")}),it("filters dashboard items by category (e.g. Cuisine)",()=>{const e=filterDashboardItems("","Cuisine");expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.category.toLowerCase()).toBe("cuisine")})}),it("returns empty array when query matches nothing",()=>{const e=filterDashboardItems("UnknownPlaceXYZ123");expect(e).toEqual([])})});